#include <cstdio>

inline long long min_ll(long long a, long long b) {
    return a < b ? a : b;
}

inline long long max_ll(long long a, long long b) {
    return a > b ? a : b;
}

long long lucky(int i) {
    return i == 1 ? 0 : lucky(i / 2) * 10 + (i % 2 == 0 ? 4 : 7);
}

int main() {
    static long long aa[2047];
    int l, r, i;
    long long x, y, ans;

    scanf("%d%d", &l, &r);
    aa[0] = 4;
    for (i = 1; i < 2047; i++)
        aa[i] = lucky(i + 1);
    ans = 0;
    for (i = 0; i < 2047; i++) {
        long long prev = (i == 0) ? 0 : aa[i - 1];
        x = max_ll(prev + 1, l);
        y = min_ll(aa[i], r);
        if (x <= y)
            ans += (y - x + 1) * aa[i];
    }
    printf("%lld\n", ans);
    return 0;
}

